adi.","ref":"reserve-2026:T060-R4-KS-M12","stem":"Dars kuzatuvidan keyin hamkasb aniq dalillar bilan feedback berdi. O‘qituvchi bir tavsiyani sinab ko‘rdi. Keyingi eng to‘g‘ri qadam?","correct":0,"options":["Yangi yondashuvning o‘quvchi natijasiga ta’sirini kuzatish","Darhol yangi sertifikat qidirish","Dalilni unutish","Tavsiya har doim to‘g‘ri deb tekshirmaslik"],"cognitive":"mulohaza","construct":"KS.06","difficulty":4},{"exp":"Hamkorlik maxfiylik va kasb etikasi talablarini saqlashi kerak.","ref":"reserve-2026:T060-R4-KS-M13","stem":"Ota-ona boshqa o‘quvchining baholari va xulqi haqida ma’lumot talab qildi. O‘qituvchi nima qilishi kerak?","correct":0,"options":["Boshqa o‘quvchining maxfiy ma’lumotini bermasdan, faqat o‘z farzandiga tegishli masalani muhokama qilish","Barcha ma’lumotni ko‘rsatish","Sinf chatiga yuborish","Baholarni taqqoslab berish"],"cognitive":"mulohaza","construct":"KS.07","difficulty":4},{"exp":"Ko‘p tomonli hamkorlik dalil va o‘quvchi manfaatiga tayangan kelishilgan qarorni talab qiladi.","ref":"reserve-2026:T060-R4-KS-M14","stem":"O‘quvchining individual ta’lim ehtiyoji bo‘yicha ota-ona va mutaxassis fikri bir-biridan farq qiladi. Eng asosli yondashuv?","correct":0,"options":["O‘quvchi manfaatini markazga qo‘yib, dalillarni birgalikda tahlil qilib kelishilgan reja tuzish","Bir tomonni eshitmasdan tanlash","Muammoni yashirish","Faqat eski rejani o‘zgartirmaslik"],"cognitive":"mulohaza","construct":"KS.07","difficulty":4},{"exp":"Rejalashtirishda natijani qanday tekshirish ham oldindan belgilanadi.","ref":"reserve-2026:T060-R4-KS-M15","stem":"Reja juda batafsil, lekin baholash usuli maqsadni tekshirmaydi. Rejani ‘yaxshi’ deb bo‘ladimi?","correct":0,"options":["Yo‘q, natijani tekshiradigan dalil oldindan rejalashtirilishi kerak","Ha, tafsilot ko‘p bo‘lsa yetarli","Baholash rejaning qismi emas","Faqat vaqt taqsimoti muhim"],"cognitive":"mulohaza","construct":"KS.01","difficulty":4},{"exp":"Individual ehtiyojni hisobga olish dars samaradorligining bir qismidir.","ref":"reserve-2026:T060-R4-KS-M16","stem":"Darsda har bir guruh bir xil ishni qiladi, lekin ayrim o‘quvchilar vazifani juda oson, boshqalari juda qiyin deb topdi. Qaysi yechim samaradorlikni oshiradi?","correct":0,"options":["Vazifa yoki yordam darajasini ehtiyojga mos differensiallash","Hammani bir xil tezlikda majburlash","Faqat kuchli o‘quvchilarni jalb qilish","Faoliyatni bekor qilish"],"cognitive":"mulohaza","construct":"KS.02","difficulty":4},{"exp":"Baholash sikli natijadan keyingi pedagogik qarorni ham o‘z ichiga oladi.","ref":"reserve-2026:T060-R4-KS-M17","stem":"Baholash natijasi o‘qituvchiga dars usulini o‘zgartirish zarurligini ko‘rsatdi, lekin u natijani faqat jurnalga yozib qo‘ydi. Qaysi bosqich yetishmayapti?","correct":0,"options":["Baholash dalili asosida ta’limni moslashtirish","Ballni yozish","Testni o‘tkazish","Davomatni tekshirish"],"cognitive":"mulohaza","construct":"KS.03","difficulty":4},{"exp":"Xavfsiz muhit qoidalarni tushunarli yetkazish va zarur harakatga tayyorlikni talab qiladi.","ref":"reserve-2026:T060-R4-KS-M18","stem":"Favqulodda vaziyatda o‘qituvchi xavfsizlik tartibini biladi, lekin o‘quvchilar bilmaydi. Bu yetarlimi?","correct":0,"options":["Yo‘q, xavfsizlik qoidalari o‘quvchilarga ham tushunarli va mashq qilingan bo‘lishi kerak","Ha, faqat o‘qituvchi bilsa yetadi","Faqat yozuv devorda bo‘lsa bo‘ldi","Favqulodda vaziyat rejalashtirilmaydi"],"cognitive":"mulohaza","construct":"KS.05","difficulty":4},{"exp":"Reja boshlang‘ich holat va ehtiyojga moslashtirilishi kerak.","ref":"reserve-2026:T060-R4-KS-Q01","stem":"Diagnostika sinfning yarmi tayanch bilimni o‘zlashtirmaganini ko‘rsatdi. O‘qituvchining eng to‘g‘ri rejalashtirish qarori qaysi?","correct":0,"options":["Reja sur’ati va tayanch topshiriqlarini natijaga moslashtirish","Eski rejani o‘zgartirmasdan davom etish","Faqat baholarni ko‘tarish","Mavzuni tashlab ketish"],"cognitive":"qollash","construct":"KS.01","difficulty":3},{"exp":"Maqsad tahlil qilish bo‘lsa, faoliyat ham tahlilni talab qilishi kerak.","ref":"reserve-2026:T060-R4-KS-Q02","stem":"Dars maqsadi ‘o‘quvchi grafikni tahlil qila oladi’. Qaysi faoliyat maqsadga eng mos?","correct":0,"options":["Grafik berib xulosa chiqarishni talab qilish","Faqat ta’rifni ko‘chirib yozdirish","Faqat video ko‘rsatish","Faqat davomat tekshirish"],"cognitive":"qollash","construct":"KS.01","difficulty":3},{"exp":"Rollar va mas’uliyat barcha o‘quvchilarni faol ishtirokga jalb qiladi.","ref":"reserve-2026:T060-R4-KS-Q03","stem":"Guruhli ishda faqat bitta o‘quvchi hamma vazifani bajaryapti. Samaradorlikni oshirish uchun nima qilish ma’qul?","correct":0,"options":["Aniq rollar va umumiy natija uchun mas’uliyat belgilash","Guruhli ishni butunlay bekor qilish","Faqat eng kuchli o‘quvchini baholash","Vazifani tushuntirmaslik"],"cognitive":"qollash","construct":"KS.02","difficulty":3},{"exp":"Bu metakognitiv refleksiya faoliyatidir.","ref":"reserve-2026:T060-R4-KS-Q04","stem":"Dars oxirida o‘quvchilar ‘nimani bildim, qayerda qiynaldim, keyingi qadamim nima’ deb yozadi. Bu nima?","correct":0,"options":["Refleksiya","Faqat nazorat ishi","Davomat","Jazo"],"cognitive":"qollash","construct":"KS.02","difficulty":3},{"exp":"Diagnostika va aniq keyingi qadamga yo‘naltirilgan feedback kerak.","ref":"reserve-2026:T060-R4-KS-Q05","stem":"O‘quvchi testda bir xil turdagi xatoni takrorlayapti. O‘qituvchi nima qilsa maqsadga muvofiq?","correct":0,"options":["Xato sababini diagnostika qilib, aniq qayta aloqa va mashq berish","Faqat umumiy ‘ko‘proq o‘qi’ deyish","Bahoni oshirish","Xatoni e’tiborsiz qoldirish"],"cognitive":"qollash","construct":"KS.03","difficulty":3},{"exp":"Vaqt bo‘yicha monitoring tendensiyani ko‘rsatadi va yordam choralarini rejalashga xizmat qiladi.","ref":"reserve-2026:T060-R4-KS-Q06","stem":"Bir o‘quvchining natijalari uch oy davomida pasayib bormoqda. Qaysi yondashuv mos?","correct":0,"options":["Monitoring ma’lumotini tahlil qilib, o‘quvchi va zarur tomonlar bilan yordam rejasini tuzish","Faqat oxirgi bahoga qarash","Faqat bir marta tanbeh berish","Ma’lumotni o‘chirib yuborish"],"cognitive":"qollash","construct":"KS.03","difficulty":3},{"exp":"Konstruktiv nizo yechimi xavfsizlik va dalilni aniqlashdan boshlanadi.","ref":"reserve-2026:T060-R4-KS-Q07","stem":"Ikki o‘quvchi o‘rtasida nizo yuz berdi. Birinchi pedagogik qadam qaysi?","correct":0,"options":["Xavfsizlikni ta’minlab, vaziyatni va tomonlarning fikrini aniqlash","Darhol bittasini aybdor qilish","Butun sinf oldida masxara qilish","Vaziyatni yashirish"],"cognitive":"qollash","construct":"KS.04","difficulty":3},{"exp":"Faol ishtirok tarbiyaviy maqsadni kuchaytiradi.","ref":"reserve-2026:T060-R4-KS-Q08","stem":"Sinf tadbiri barcha o‘quvchilarni faqat tomoshabin qoldirmoqda. Tarbiyaviy samarani oshirish uchun nima qilish kerak?","correct":0,"options":["O‘quvchilarga mazmunli rol va mas’uliyat berish","Tadbir vaqtini uzaytirish","Faqat o‘qituvchi gapirsin","Faqat suratga olish"],"cognitive":"qollash","construct":"KS.04","difficulty":3},{"exp":"Ehtiyojga mos format teng ishtirokni qo‘llab-quvvatlaydi.","ref":"reserve-2026:T060-R4-KS-Q09","stem":"Eshitishida qiyinchiligi bo‘lgan o‘quvchi og‘zaki ko‘rsatmani yaxshi anglamayapti. Eng mos qo‘llab-quvvatlash qaysi?","correct":0,"options":["Ko‘rsatmani yozma/ko‘rgazmali shakl bilan ham berish","Uni faoliyatdan chiqarish","Vazifani bekor qilish","Faqat tezroq gapirish"],"cognitive":"qollash","construct":"KS.05","difficulty":3},{"exp":"Jismoniy xavfsizlik xavfni oldindan bartaraf etishni talab qiladi.","ref":"reserve-2026:T060-R4-KS-Q10","stem":"Kompyuter xonasida kabel yo‘lakdan o‘tib qolgan. Eng to‘g‘ri harakat?","correct":0,"options":["Xavfni darhol bartaraf etib, texnika xavfsizligini tiklash","E’tiborsiz qoldirish","Faqat rasmga olish","O‘quvchilarga undan sakrab o‘tishni aytish"],"cognitive":"qollash","construct":"KS.05","difficulty":3},{"exp":"Refleksiya rivojlanish ehtiyojini amaliy o‘zgarish va qayta baholash bilan bog‘laydi.","ref":"reserve-2026:T060-R4-KS-Q11","stem":"O‘qituvchi dars kuzatuvida savollar faqat kuchli o‘quvchilarga berilayotganini sezdi. Keyingi kasbiy rivojlanish qadami qaysi?","correct":0,"options":["Savol berish strategiyasini o‘rganib, amaliyotda sinab va natijani qayta kuzatish","Faqat sertifikat olish","Muammoni inkor qilish","Faqat o‘quvchilarni almashtirish"],"cognitive":"qollash","construct":"KS.06","difficulty":3},{"exp":"Kasbiy o‘sish yangi bilimni amaliyotga kiritish va natijasini tahlil qilishni talab qiladi.","ref":"reserve-2026:T060-R4-KS-Q12","stem":"Seminarda o‘rganilgan metodni darsga qo‘llashdan keyin nima qilish muhim?","correct":0,"options":["O‘quvchi natijasi va kuzatuv orqali samarani baholash","Faqat sertifikatni saqlash","Metodni doimiy o‘zgartirmasdan ishlatish","Natijani tekshirmaslik"],"cognitive":"qollash","construct":"KS.06","difficulty":3},{"exp":"Professional hamkorlik dalil, tinglash va yechimga tayanadi.","ref":"reserve-2026:T060-R4-KS-Q13","stem":"Ota-ona farzandining past natijasidan norozi. O‘qituvchining eng to‘g‘ri javobi qaysi?","correct":0,"options":["Dalillarni ko‘rsatib, ota-onani tinglab, birgalikda keyingi qadamni belgilash","Ota-onani ayblash","Boshqa o‘quvchilarning maxfiy baholarini ko‘rsatish","Muloqotni to‘xtatish"],"cognitive":"qollash","construct":"KS.07","difficulty":3},{"exp":"Ko‘p tomonlama muammo hamkorlikda muvofiqlashtirilgan yondashuvni talab qiladi.","ref":"reserve-2026:T060-R4-KS-Q14","stem":"O‘quvchining qiyinchiligi bir nechta fanlarda kuzatilmoqda. Qaysi yondashuv asosli?","correct":0,"options":["Tegishli fan o‘qituvchilari va mutaxassislar bilan kelishilgan yordamni muvofiqlashtirish","Har o‘qituvchi mustaqil, bir-biridan bexabar ishlasin","Muammoni ota-onadan yashirish","Faqat bahoni pasaytirish"],"cognitive":"qollash","construct":"KS.07","difficulty":3},{"exp":"Sifatli feedback kuchli tomon, xato va aniq keyingi qadamni ko‘rsatadi.","ref":"reserve-2026:T060-R4-KS-Q15","stem":"O‘quvchi topshiriqda 6/10 oldi. Qaysi feedback foydaliroq?","correct":0,"options":["‘6/10. Formulani to‘g‘ri tanlading, lekin birliklarni aylantirishni tekshir; 2–3-masalani qayta ishlagin.’","‘Yomon.’","Faqat ‘6’ deb yozish","Hech qanday izoh bermaslik"],"cognitive":"qollash","construct":"KS.03","difficulty":3}]'::jsonb)
 loop
  if exists(select 1 from public.questions where source_reference=item->>'ref') then
   continue;
  end if;

  select c.id,c.subject_id,c.group_code
    into v_construct,v_subject,v_group
    from public.constructs c
   where c.code=item->>'construct'
     and c.is_active;

  if v_construct is null then
   raise exception 'TASK-060 R4 construct not found: %',item->>'construct';
  end if;

  select l.id into v_lesson
    from public.lesson_constructs lc
    join public.lessons l on l.id=lc.lesson_id
   where lc.construct_id=v_construct
     and l.status='published'::public.content_status
   order by case when coalesce(l.body_mdx,'')<>'' then 0 else 1 end,l.order_idx,l.id
   limit 1;

  if v_lesson is null then
   raise exception 'TASK-060 R4 source lesson not found: %',item->>'construct';
  end if;

  v_question:=gen_random_uuid();
  insert into public.questions(
    id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,
    assets,is_generated,status,author_id,source_reference,source_lesson_id
  ) values (
    v_question,v_subject,v_construct,v_group,
    'Y1'::public.question_format,
    (item->>'cognitive')::public.cognitive_level,
    (item->>'difficulty')::int,
    item->>'stem','[]'::jsonb,false,'published'::public.content_status,
    null,item->>'ref',v_lesson
  );

  v_correct:=(item->>'correct')::int;
  for v_i in 0..3 loop
   v_option:=gen_random_uuid();
   insert into public.question_options(id,question_id,content_md,order_idx)
   values(v_option,v_question,item->'options'->>v_i,v_i);
   if v_i=v_correct then
    insert into public.question_keys(question_id,payload,explanation_md)
    values(v_question,jsonb_build_object('correct_option_id',v_option),item->>'exp');
   end if;
  end loop;
 end loop;
end
$$;

